[] a sh:ValidationReport ;
    sh:conforms true .

@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Product,
                        schema1:Thing ;
                    schema1:additionalType <https://www.wikidata.org/wiki/Q3099911>,
                        "TEM" ;
                    schema1:name "missing" ] ;
            sh:resultMessage "An instrument must have an identifier (schema:identifier)." ;
            sh:resultPath schema1:identifier ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "An instrument must have an identifier (schema:identifier)." ;
                    sh:minCount 1 ;
                    sh:path schema1:identifier ] ] .

